"""v27.4 — General ENT / Emergencies final seven exact-canonical ladders."""
DOMAIN="General ENT / Emergencies"
def _q(qid,topic,stage,stem,choices,answer,exp,reasons,pearl,curveball,focus="boards"):
 return {"id":qid,"domain":DOMAIN,"topic":topic,"learning_stage":stage,"stem":stem,"choices":choices,"answer":answer,"explanation":exp,"why_wrong":reasons,"board_pearl":pearl,"curveball":curveball,"tier":"Curated learning ladder","mode":"Vignette","focus":focus,"ladder_reviewed":True,"_coverage_reviewed_v211":True}
VIGNETTES_V274=[
_q("v274_gen_wound_fnd","Wound Healing / Scar Biology in Head & Neck Surgery","foundation","Which event most directly characterizes the proliferative phase of normal wound healing?",["Fibroblast proliferation, angiogenesis, granulation tissue formation, and collagen deposition","Immediate platelet aggregation only","Late collagen remodeling with falling cellularity","Mature scar contraction after complete epithelialization"],0,"The proliferative phase follows hemostasis/inflammation and features fibroblasts, neovascularization, granulation tissue, epithelial migration, and matrix deposition.",["Correct. These are defining proliferative-phase events.","Platelet aggregation is primarily hemostatic and occurs earlier.","Collagen reorganization and declining cellularity characterize remodeling.","Scar contraction can occur during healing but does not define the proliferative phase by itself."],"Know hemostasis/inflammation, proliferation, and remodeling as overlapping biologic phases rather than isolated dates.","How do radiation, diabetes, nicotine, and malnutrition alter these phases?"),
_q("v274_gen_wound_app","Wound Healing / Scar Biology in Head & Neck Surgery","application","A previously irradiated neck incision separates with devitalized edges and exposed hardware. What management principle is most important?",["Control infection and necrosis, optimize systemic factors, debride nonviable tissue, and obtain durable vascularized coverage rather than repeatedly closing compromised edges under tension","Simply re-suture the same edges tightly at bedside","Delay evaluation until granulation covers the hardware","Inject intralesional steroid into the open wound"],0,"Radiation impairs vascularity and tissue reserve. Dehiscence with exposed hardware requires source control, debridement, optimization, and often vascularized tissue coverage.",["Correct. Durable healing requires viable tissue and control of the local/systemic causes of failure.","Closing ischemic contaminated edges under tension commonly fails again.","Exposed hardware and devitalized tissue warrant active evaluation rather than passive delay.","Steroid can impair healing and is not treatment for an open infected or ischemic wound."],"A failing wound is usually a biology and mechanics problem before it is a suture problem.","What findings would make free-tissue transfer preferable to local rearrangement?","senior_decision"),
_q("v274_gen_wound_snr","Wound Healing / Scar Biology in Head & Neck Surgery","senior_decision","A patient develops a widening hypertrophic neck scar three months after surgery and requests immediate excision. What is the best senior approach?",["Identify ongoing tension and scar biology, use appropriate conservative scar therapy while maturation continues, and reserve revision for a stable scar unless function or another urgent indication demands earlier intervention","Excise every hypertrophic scar immediately at three months","Reassure that no scar intervention is ever useful","Perform revision without addressing tension vectors or patient-specific risk factors"],0,"Most scars remodel for many months. Early hypertrophy often benefits from silicone, sun protection, massage when appropriate, and selected steroid/laser strategies; revision should address the mechanical cause as well as timing.",["Correct. Scar treatment should match maturation, symptoms, and mechanics.","Premature excision may recreate the same biology and tension before maturation.","Symptomatic or cosmetically significant scars often have useful nonsurgical and surgical options.","Ignoring tension and risk factors predisposes to recurrence."],"Scar revision succeeds when you revise the vector and biology, not merely the line.","When would contracture threatening eyelid, airway, or neck motion justify earlier surgery?","senior_decision"),
_q("v274_gen_graft_fnd","Grafts / Implants / Biomaterials in ENT","foundation","Which statement best distinguishes a graft from a vascularized flap?",["A graft initially survives by diffusion and then revascularization from its recipient bed, whereas a flap is transferred with an intrinsic blood supply","A graft always contains its own named artery","A flap can survive equally well on an avascular infected bed","Implants and autologous grafts have identical infection behavior"],0,"Free grafts depend on plasmatic imbibition and inosculation/revascularization; flaps retain a vascular pedicle or microvascular inflow/outflow.",["Correct. Recipient-bed biology is crucial for graft survival.","A named intrinsic vascular supply defines a flap, not a free graft.","Even vascularized tissue can fail in uncontrolled infection; an avascular bed is especially poor for graft take.","Synthetic implants and autologous tissue differ in biofilm, extrusion, and integration risk."],"Ask whether the reconstructive tissue brings blood supply with it.","Why does irradiated or exposed-bone recipient tissue change graft choice?"),
_q("v274_gen_graft_app","Grafts / Implants / Biomaterials in ENT","application","A septal reconstruction requires structural support in a contaminated field with thin soft-tissue coverage. Which principle should guide material choice?",["Favor biologically compatible autologous tissue when feasible and minimize permanent foreign material where infection, extrusion, or poor coverage risk is high","Use the largest permanent alloplastic implant available because contamination does not affect extrusion risk","Choose material solely by cost because biomechanics are interchangeable","Place porous implant directly beneath compromised skin without vascularized coverage"],0,"Material choice balances mechanical demand, donor morbidity, contour, resorption/warping, infection risk, and soft-tissue coverage. Autologous cartilage or bone is often preferred in contaminated or high-risk beds.",["Correct. Material biology and recipient-bed quality matter as much as shape.","Permanent foreign material has increased infection/biofilm/extrusion concerns in contaminated fields.","Biomaterials have distinct mechanical and biologic properties.","Poor soft-tissue coverage increases exposure and extrusion risk."],"Choose the reconstructive material for the bed you have, not just the defect you see.","When might vascularized tissue be needed before any structural implant?","or_prep"),
_q("v274_gen_graft_snr","Grafts / Implants / Biomaterials in ENT","senior_decision","A patient has recurrent infection around a permanent facial implant despite antibiotics and drainage. What is the best senior management principle?",["Suspect biofilm and inadequate source control; remove infected foreign material when salvage is unlikely, control infection, and reconstruct after or with durable vascularized coverage as appropriate","Continue indefinite oral antibiotics without reassessing the implant","Add a second implant to stabilize the infected one","Close the draining sinus tightly while leaving all infected material in place"],0,"Persistent implant infection often reflects biofilm, where antibiotics alone cannot sterilize the device. Definitive source control may require explantation and staged or immediate reconstruction depending on contamination and tissue quality.",["Correct. Chronic device infection is fundamentally a source-control problem.","Suppressive antibiotics may have selected roles but are not reliable definitive therapy for a persistently infected removable implant.","Additional foreign material worsens the source-control problem.","Closing a draining tract over retained infected material can worsen deep infection."],"When hardware is the nidus, cure may require removing the nidus.","What factors would justify immediate versus staged reconstruction?","senior_decision"),
_q("v274_gen_sys_fnd","Systemic / Granulomatous Disease Manifestations in ENT","foundation","Which ENT finding should raise concern for granulomatosis with polyangiitis rather than routine localized disease?",["Destructive chronic sinonasal inflammation with crusting, septal damage, and possible subglottic stenosis in a patient with systemic inflammatory features","Isolated uncomplicated viral rhinitis","Single cerumen impaction","Stable congenital preauricular pit"],0,"GPA can produce destructive sinonasal disease, otologic disease, subglottic stenosis, and pulmonary/renal manifestations; diagnosis integrates clinical pattern, labs, imaging, and often biopsy.",["Correct. Multisite destructive inflammatory disease should trigger systemic evaluation.","Viral rhinitis is self-limited and nondestructive.","Cerumen impaction does not suggest vasculitis.","A congenital pit is unrelated to granulomatous vasculitis."],"ENT may be the first specialty to see systemic vasculitis before renal or pulmonary disease is recognized.","What findings make tissue diagnosis urgent before immunosuppression?"),
_q("v274_gen_sys_app","Systemic / Granulomatous Disease Manifestations in ENT","application","A patient has refractory crusting sinus disease, new saddle-nose deformity, hematuria, and pulmonary nodules. What is the best next approach?",["Treat this as possible systemic vasculitis: coordinate urgent systemic workup, obtain appropriate tissue when feasible, and assess renal/pulmonary threat rather than escalating topical sinus therapy alone","Perform cosmetic rhinoplasty first","Assume isolated chronic rhinosinusitis because nasal symptoms came first","Start prolonged antifungal therapy without diagnostic evaluation"],0,"The combination of destructive ENT disease plus renal and pulmonary findings is a systemic red flag. Life-threatening organ involvement and diagnostic confirmation take priority over local symptom treatment.",["Correct. The pattern demands coordinated systemic evaluation and tissue diagnosis when safe.","Cosmetic reconstruction should wait until disease control and diagnosis are established.","Multisystem disease cannot be explained by routine isolated CRS.","Empiric antifungal therapy without evidence can delay the correct vasculitis diagnosis."],"When ENT destruction meets kidney or lung disease, stop thinking organ-by-organ.","How would suspected invasive fungal disease alter urgency and biopsy strategy?","overnight_call"),
_q("v274_gen_sys_snr","Systemic / Granulomatous Disease Manifestations in ENT","senior_decision","A patient with known GPA has worsening stridor and fixed subglottic narrowing during an apparent systemic flare. What is the best senior principle?",["Assess airway severity immediately and coordinate local airway intervention with systemic disease control; do not rely on systemic immunosuppression alone if critical fixed obstruction is present","Wait for immunosuppression to work regardless of airway compromise","Perform definitive open reconstruction during uncontrolled active inflammation without assessing alternatives","Treat only with inhaled decongestant"],0,"GPA airway disease can combine inflammatory activity with fixed scar. Threatened airway requires immediate severity assessment and sometimes endoscopic or surgical intervention while rheumatologic therapy treats active disease.",["Correct. Airway safety and systemic control often need parallel treatment.","Critical fixed stenosis may not improve fast enough with medication alone.","Open reconstruction in uncontrolled active disease may have poor healing/recurrence and must be individualized.","Topical decongestant does not treat subglottic stenosis."],"Systemic disease does not make a mechanical airway obstruction less mechanical.","Which features suggest inflammatory edema versus mature cicatricial stenosis?","senior_decision"),
_q("v274_gen_laser_fnd","Laser / Energy Safety in Otolaryngology","foundation","During airway laser surgery, which combination most directly reduces operating-room fire risk?",["Use the lowest feasible inspired oxygen concentration, avoid nitrous oxide, protect the airway with laser-safe strategies, and communicate before laser activation","Increase oxygen to 100% during laser activation","Allow alcohol-based prep to remain wet beneath drapes","Activate the laser before announcing it to anesthesia"],0,"Fire prevention requires control of oxidizer, ignition source, and fuel. Airway laser cases demand explicit team communication and laser-safe airway planning.",["Correct. Reducing oxidizer concentration and protecting fuel sources are core fire-prevention measures.","High FiO2 increases oxidizer concentration and fire severity.","Wet alcohol prep is flammable fuel.","Unannounced activation defeats team coordination around oxidizer and airway protection."],"Think fire triangle: oxidizer, ignition, fuel.","What immediate actions are required if an endotracheal tube ignites?"),
_q("v274_gen_laser_app","Laser / Energy Safety in Otolaryngology","application","During microlaryngoscopy with CO2 laser, the tube cuff suddenly ignites. What should happen first?",["Stop laser and ventilation, disconnect oxygen, remove the burning tube, extinguish with saline, then re-establish and evaluate the airway for thermal injury","Continue ventilation through the burning tube to maintain oxygen saturation","Leave the tube in place and obtain a chest radiograph first","Increase nitrous oxide to dilute oxygen"],0,"Airway fire is an immediate emergency: stop gases/ignition, remove burning material, extinguish, then secure the airway and perform endoscopic assessment for residual material and thermal injury.",["Correct. Source control of the fire precedes routine diagnostics.","Ventilating feeds oxidizer to the fire and can worsen distal injury.","Imaging must not delay removal of the burning fuel source.","Nitrous oxide supports combustion and should not be used."],"Airway fire management is memorized choreography because hesitation worsens injury.","When would bronchoscopy and ICU observation be indicated after apparent rapid extinguishment?","overnight_call"),
_q("v274_gen_laser_snr","Laser / Energy Safety in Otolaryngology","senior_decision","A case requires laser work near an airway lesion but adequate exposure would require unsafe FiO2 and the tube cannot be protected reliably. What is the best senior decision?",["Change the airway/energy plan or abort laser use until the fire risk is acceptably controlled rather than proceeding because the planned device is convenient","Proceed because laser fire is too rare to alter the plan","Use nitrous oxide to reduce oxygen concentration","Cover the tube with dry gauze and proceed"],0,"Senior judgment includes refusing an unsafe fire triangle. Alternative ventilation, different instrumentation, staged airway management, or nonlaser techniques may be safer.",["Correct. The procedure must adapt to the safety envelope.","Low-frequency catastrophic complications still demand prevention.","Nitrous oxide supports combustion.","Dry gauze is fuel, not reliable laser protection."],"The correct operation is the one you can perform safely, not the one originally scheduled.","Which airway strategies can reduce oxidizer and tube exposure in selected cases?","senior_decision"),
_q("v274_gen_evidence_fnd","Evidence Interpretation / Outcomes Research","foundation","What does a 95% confidence interval around a treatment effect primarily communicate?",["A range of effect estimates compatible with the observed data under the model, conveying precision as well as whether clinically important effects remain plausible","The probability that 95% of individual patients will benefit","Proof that the study is unbiased","The percentage of missing data"],0,"Confidence intervals summarize estimate precision and plausible effect sizes under repeated-sampling assumptions. They should be interpreted with clinical importance, not only p-value thresholds.",["Correct. The interval adds magnitude and precision information beyond dichotomous significance.","It does not mean 95% of patients benefit.","Bias can persist despite a narrow confidence interval.","Missingness is a separate study-quality issue."],"Read effect size and confidence interval before celebrating a p value.","How would a narrow CI around a clinically trivial effect change your conclusion?"),
_q("v274_gen_evidence_app","Evidence Interpretation / Outcomes Research","application","A retrospective study reports lower postoperative complications with technique A, but surgeons selected technique A for healthier patients. What is the central threat to causal interpretation?",["Confounding by indication/selection because baseline prognosis influenced treatment assignment","Type I error only","Recall bias cannot occur in retrospective data","Perfect randomization"],0,"When treatment choice depends on patient risk, observed outcomes may reflect baseline differences rather than treatment effect. Adjustment or propensity methods can reduce measured confounding but cannot remove unmeasured confounding.",["Correct. Nonrandom treatment assignment creates confounding that must be addressed explicitly.","Statistical significance is not the only threat; systematic baseline differences can dominate.","Retrospective designs can have several information biases depending on data collection.","The study is explicitly nonrandomized."],"Association after adjustment is not automatically causation.","What balance diagnostics would you inspect after propensity matching?","boards"),
_q("v274_gen_evidence_snr","Evidence Interpretation / Outcomes Research","senior_decision","A new surgical technique shows a statistically significant 1-point improvement on a 100-point symptom scale with no difference in complications. How should a chief interpret the result before changing practice?",["Examine the minimally important clinical difference, confidence interval, bias, follow-up, generalizability, and tradeoffs rather than equating statistical significance with meaningful benefit","Adopt it immediately because p<0.05 proves superiority","Reject all patient-reported outcomes as invalid","Ignore confidence intervals once significance is reached"],0,"Practice change requires clinical as well as statistical importance, credible methods, relevant harms, durability, and applicability to the intended population.",["Correct. Evidence interpretation is a decision problem, not a p-value contest.","Statistical significance may represent a clinically negligible difference.","Validated patient-reported outcomes can be important endpoints.","Confidence intervals remain essential for magnitude and precision."],"Chief-level evidence appraisal asks: is the effect real, meaningful, durable, and worth the tradeoff?","How would noninferiority design change the questions you ask?","senior_decision"),
_q("v274_gen_frail_fnd","Geriatric Otolaryngology / Frailty","foundation","Why is frailty clinically different from chronological age alone?",["Frailty reflects diminished physiologic reserve and vulnerability to stress, often predicting postoperative complications and loss of independence beyond age alone","Frailty simply means age over 65","Frailty is identical to ASA class","Frailty affects only orthopedic surgery"],0,"Frailty integrates functional, nutritional, cognitive, and physiologic reserve. It can identify older patients who may tolerate the same operation very differently despite similar age.",["Correct. Reserve and vulnerability are the core concepts.","Many older adults are robust and some younger adults are frail.","ASA and frailty overlap but measure different constructs.","Frailty influences outcomes across surgical specialties, including head and neck surgery."],"Age tells you how long someone has lived; frailty helps estimate how much physiologic reserve remains.","Which bedside frailty features most change discharge planning?"),
_q("v274_gen_frail_app","Geriatric Otolaryngology / Frailty","application","An 82-year-old with resectable head-and-neck cancer is independent but has recent weight loss, slow gait, polypharmacy, and mild cognitive impairment. What is the best preoperative approach?",["Perform geriatric/frailty assessment, optimize nutrition and medications, anticipate delirium and functional needs, and incorporate these risks into shared decision-making rather than using age alone to deny treatment","Cancel curative surgery solely because the patient is over 80","Ignore cognition because it does not affect postoperative outcomes","Plan routine discharge home without evaluating support"],0,"Frailty assessment identifies modifiable risks and predicts delirium, prolonged hospitalization, complications, and nonhome discharge. Chronologic age alone should not decide candidacy.",["Correct. Risk stratification should guide optimization and goals-concordant planning.","Age alone is an inadequate proxy for physiologic reserve.","Baseline cognitive impairment increases delirium and recovery risk.","Support needs should be planned before surgery."],"Frailty assessment is useful because it changes preparation and disposition, not because it supplies a veto score.","What findings would shift the discussion toward less morbid oncologic options?","preop"),
_q("v274_gen_frail_snr","Geriatric Otolaryngology / Frailty","senior_decision","A frail older patient develops hypoactive delirium, poor intake, and functional decline after major head-and-neck surgery. What is the best senior management principle?",["Search for reversible drivers such as infection, hypoxia, medication effects, pain, urinary retention, dehydration, and electrolyte problems while mobilizing early, preserving sleep/orientation, and minimizing deliriogenic medications","Treat hypoactive delirium as normal aging and observe","Use benzodiazepines routinely for all delirium","Keep the patient on bed rest until cognition normalizes"],0,"Postoperative delirium is often multifactorial. Nonpharmacologic prevention/treatment plus correction of triggers and early mobility reduce downstream functional decline.",["Correct. Delirium is a medical complication requiring cause-finding and supportive recovery measures.","New delirium is not a benign consequence of age.","Benzodiazepines can worsen most delirium outside specific withdrawal indications.","Bed rest accelerates deconditioning and loss of independence."],"Hypoactive delirium is easy to miss and just as consequential as agitation.","When does persistent delirium require neuroimaging or specialty consultation?","senior_decision"),
_q("v274_gen_oral_fnd","Oral Manifestations of Systemic Disease","foundation","Which oral finding is a classic clue to iron, vitamin B12, or folate deficiency?",["Atrophic glossitis with a smooth painful tongue","Isolated torus mandibularis","Stable linea alba","Congenital geographic tongue alone"],0,"Nutritional and hematologic deficiencies can cause glossitis, angular cheilitis, mucosal pallor, ulceration, or burning symptoms, but findings are not specific and require clinical correlation.",["Correct. Smooth erythematous painful tongue is a classic deficiency-associated pattern.","Tori are benign bony variants.","Linea alba is usually frictional and benign.","Geographic tongue is common and not a specific deficiency marker."],"Oral examination can be the first clue to anemia, immune disease, endocrine disease, or medication toxicity.","What laboratory pattern would distinguish iron from B12 deficiency?"),
_q("v274_gen_oral_app","Oral Manifestations of Systemic Disease","application","A patient has persistent painful oral ulcerations, ocular inflammation, and genital ulcers. What is the best next step?",["Recognize a possible systemic inflammatory disorder such as Behcet disease and coordinate systemic evaluation rather than treating every lesion as isolated aphthae","Assume recurrent trauma and cauterize all lesions","Start empiric antifungals indefinitely without evidence of candidiasis","Biopsy only the normal mucosa"],0,"Recurrent oral ulcers plus ocular and genital inflammation suggest systemic disease. ENT should identify the pattern, exclude dangerous mimics, and coordinate specialty evaluation.",["Correct. Multisite mucosal inflammatory disease needs systemic synthesis.","Trauma does not explain the systemic pattern.","Antifungals do not treat aphthous/systemic inflammatory ulcers without fungal evidence.","Biopsy should target an informative active lesion when tissue diagnosis is needed."],"The mouth often reveals systemic disease before the referral label does.","Which ulcer features instead demand urgent malignancy workup?","boards"),
_q("v274_gen_oral_snr","Oral Manifestations of Systemic Disease","senior_decision","An immunosuppressed patient has a progressive painful palatal ulcer with necrosis despite topical therapy. What is the best senior approach?",["Escalate urgently for tissue diagnosis and imaging as indicated to exclude invasive infection, malignancy, or vasculitic necrosis rather than assuming benign aphthous disease","Continue topical steroid alone for several weeks","Reassure because oral ulcers are common","Debride extensively before defining vascularity, infection, or malignancy"],0,"Progressive necrotic ulceration in an immunosuppressed host can represent invasive fungal infection, neoplasm, viral disease, or vasculitis. Delay can be catastrophic; tissue and anatomic evaluation are often required urgently.",["Correct. Host risk plus progressive necrosis lowers the threshold for urgent biopsy and imaging.","Steroid monotherapy may worsen occult infection and delays diagnosis.","Common benign ulcers should improve and lack this high-risk context.","Blind extensive debridement before diagnosis can be harmful and incomplete."],"Necrosis plus immunosuppression is a diagnostic emergency until proved otherwise.","What endoscopic or imaging findings would suggest invasive fungal spread toward orbit or skull base?","overnight_call")]
def apply_learning_ladders_v274(challenges, concept_lookup):
 existing={str(q.get("id")) for q in challenges}
 added=0
 for q in VIGNETTES_V274:
  row=dict(q); row["concept_id"]=concept_lookup(DOMAIN,row["topic"])
  if not row["concept_id"]: raise ValueError(f"v27.4 canonical lookup failed: {row['topic']}")
  if row["id"] not in existing: challenges.append(row); existing.add(row["id"]); added+=1
 return {"added":added,"topics":len({q['topic'] for q in VIGNETTES_V274})}
